from collections import Counter, defaultdict


def transform(grid):
    h, w = len(grid), len(grid[0])
    stripes = defaultdict(list)
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                stripes[r + c].append(grid[r][c])
    clues = {}
    for k, vals in stripes.items():
        counts = Counter(vals)
        clues[k] = counts.most_common(1)[0][0]

    keys = sorted(clues)
    if not keys:
        raise ValueError("no diagonal stripes")
    span = max(keys) - min(keys) + 1
    period = span
    for p in range(1, span + 1):
        seen = {}
        valid = True
        for k, color in clues.items():
            residue = k % p
            if residue in seen and seen[residue] != color:
                valid = False
                break
            seen[residue] = color
        if valid:
            period = p
            break

    known = {k % period: color for k, color in clues.items()}
    palette = {}
    for residue in range(period):
        if residue in known:
            palette[residue] = known[residue]
        else:
            source = min(known, key=lambda k: (min((residue-k) % period, (k-residue) % period), (residue-k) % period))
            palette[residue] = known[source]
    return [[palette[(r + c) % period] for c in range(w)] for r in range(h)]


